const manuals={label:"Toyota Camry manuals and warranty guides",url:"https://www.toyota.com/owners/warranty-owners-manuals/",note:"Official Toyota model-year owner-document lookup; repair procedures require VIN-correct Toyota service information"};
const misfireV6={label:"Toyota T-SB-0071-18 Rev2 — 2018 Camry V6 high-load misfire",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10185782-9999.pdf",note:"2018 Camry 2GR-FKS with P030000/P030027/P030085 and possible cylinder 5/6 misfire; narrow calibration and inspection procedure"};
const coolant={label:"Toyota T-SB-0045-13 — 2010–2011 Camry P0128",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10061560-2280.pdf",note:"2010–2011 Camry 2AR-FE with 6AT and specified VDS/emissions calibrations; bulletin does not apply when other DTCs are present"};
const oxygenOld={label:"Toyota T-SB-0001-10 Rev1 — Camry P0138 diagnostic tips",url:"https://static.nhtsa.gov/odi/tsbs/2013/MC-10132202-9999.pdf",note:"Listed 2007–2010 Camry V6 applications; explains possible incorrect upstream A/F-sensor response with P0138/P0158"};
const oxygen2ar={label:"Toyota T-SB-0151-18 — 2010–2011 Camry 2AR-FE P0138",url:"https://static.nhtsa.gov/odi/tsbs/2018/MC-10153198-9999.pdf",note:"Non-PZEV 2010–2011 Camry 2AR-FE only; requires application and calibration confirmation"};
const evapLogic={label:"Toyota 2AZ-FE EVAP monitor description",url:"https://static.nhtsa.gov/odi/inv/2004/INRD-PE04021-18337.pdf",note:"Toyota engineering/repair-manual material describing 2002 Camry P0441 monitor valve sequence; useful only for that EVAP generation"};

const vehicle={name:"Toyota Camry",kicker:"TOYOTA CAMRY · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Toyota Camry",about:"Toyota Camry engine and emissions diagnostics",yearsIntro:"Camry is not one diagnostic application. Older 2AZ-FE and 1MZ/3MZ engines, 2AR-FE/2GR-FE, 2018+ A25A-FKS/2GR-FKS and hybrid powertrains use different sensors, fuel systems, EVAP hardware, timing controls and monitor logic. Confirm model year, VIN, engine code, hybrid status and emissions certification before selecting a repair procedure."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle"|"yearNotes"|"sources"|"deepDive"|"closing">&{slug:string;yearNotes:string[];sources?:TroubleCodeGuide["sources"];deepDive?:NonNullable<TroubleCodeGuide["deepDive"]>};

function page(x:Input):TroubleCodeGuide{return{...x,slug:`toyota/camry/${x.slug}`,vehicle,yearNotes:[...x.yearNotes,"Confirm the engine family from the emissions label or VIN catalog before ordering parts; cylinder banks, sensor names, specifications and monitor conditions are not interchangeable.","A Toyota bulletin is a diagnostic branch for its listed year, engine, VDS and calibration—not proof that every Camry with the same code needs that repair.","Save confirmed, pending and permanent codes, readiness and the first freeze frame before clearing memory or disconnecting the battery."],deepDive:[...(x.deepDive??[]),{heading:`How to read Camry scan data for ${x.code}`,paragraphs:[`Preserve the first freeze frame for ${x.code}: rpm, calculated load, coolant and intake-air temperature, vehicle speed, fuel level, battery voltage and time since start. Those values reveal whether the monitor failed after an overnight soak, during warm-up, at idle, during cruise/deceleration or under high load. Testing in a different state can make an intermittent fault look normal.`,`Read companion codes as a system. Circuit and reference-voltage faults move electrical diagnosis ahead of component replacement. Repair active misfire and mixture faults before judging catalyst or oxygen-sensor performance. On a hybrid, distinguish engine run time from vehicle READY time because the gasoline engine may cycle off.`,`Graph related signals on one time scale and label units. Compare desired with actual VVT angle, both fuel trims, temperature sensors after a cold soak, or commanded valve state with tank-pressure response. A single screenshot at warm idle rarely proves a performance code.`]},{heading:"Useful owner checks and professional boundaries",paragraphs:["With the engine cold, an owner can inspect oil and coolant levels, the air-filter housing and duct, battery terminals, accessible grounds, the fuel cap/seal where equipped, and connectors or hoses disturbed during recent service. Photograph the original condition before moving anything.","Use trained service equipment for regulated EVAP smoke, bidirectional purge/vent commands, fuel-pressure testing, energized electronic throttle work, oscilloscope cam/crank correlation, cooling-system pressure testing, compression/leak-down and hybrid high-voltage areas. Fuel vapor, hot coolant, moving engine parts and high voltage create separate hazards.","Ask which test failed, under what operating condition, and which engine-specific Toyota procedure was followed. A diagnosis written only as ‘code present—replace sensor’ does not separate the sensor from wiring, plumbing, calibration or the upstream condition it reported."]},{heading:"How Toyota bulletins fit the diagnosis",paragraphs:["Match the complete applicability table: model year, engine, transmission, VDS/WMI, emissions certification, production range and calibration where listed. Similar code wording on another generation does not extend the document.","Follow the sequence and exclusions. Some Toyota bulletins apply only when no additional DTCs are present or only after a specific symptom is reproduced. If the conditions fail, return to the normal repair-manual diagnostic tree instead of forcing the bulletin repair.","A TSB is not automatically a recall or free repair. Warranty and campaign eligibility are VIN-, date- and mileage-specific. Verify current status with Toyota and keep the bulletin as technical evidence, not a promise of coverage."]},{heading:"Verification after the Camry repair",paragraphs:[`Clear ${x.code} only after preserving evidence and correcting a proven cause. Reinspect every disturbed hose, seal, connector, clamp and fluid level, then observe the relevant PIDs at idle before attempting a road test.`,`Repeat the safe portion of the original freeze-frame condition. An EVAP monitor may need a particular fuel level and soak; P0128 requires a true cold warm-up; a load misfire must not be reproduced aggressively if the lamp flashes; correlation faults require quiet, safe engine operation.`,`Check pending codes after the drive and allow readiness to progress without repeated resets. Permanent codes clear after enough passing monitor operation—not merely because battery power was removed. Retain before-and-after reports.`]}],closing:{title:`When the ${x.code} diagnosis is complete`,paragraphs:[`The repair is complete when the original operating condition is reproduced safely, the monitored values behave normally and no pending ${x.code} or related fault returns. An extinguished lamp immediately after clearing is not proof.`,`Recheck for fuel vapor, intake, exhaust, coolant and oil leaks plus anything disturbed during diagnosis. If weather, temperature or fuel level prevents the original monitor from running, document that limitation rather than claiming certainty.`,`If the code returns, compare the new freeze frame with the original. A matching pattern suggests incomplete root-cause correction; a different load, temperature or companion-code pattern may reveal a second fault.`]},sources:[...(x.sources??[]),manuals]};}

const commonFreeze=["Confirmed, pending and permanent codes","RPM, load, speed and coolant temperature","Battery voltage and time since start","Recent service, refueling and symptom history"];

export const troubleCodeCamry:TroubleCodeGuide[]=[
page({slug:"p0171",code:"P0171",title:"P0171 Code Toyota Camry: Lean Mixture Causes and Fuel-Trim Tests",description:"Diagnose Toyota Camry P0171 using idle-versus-load fuel trims, intake and purge leak tests, fuel pressure, exhaust inspection and engine-specific data.",definition:"System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration until fuel delivery and misfire are checked. Stop for a flashing lamp, severe hesitation, detonation, overheating or stalling. A smooth-running car with a steady lamp may permit a short diagnostic trip, but prolonged lean operation can damage the catalyst or engine.",quickAnswer:"P0171 means Bank 1 fuel correction exceeded Toyota's calibrated lean limit. It does not say the air/fuel or oxygen sensor failed. Compare short- and long-term trims at warm idle and higher airflow; then test unmetered intake/PCV air, purge flow, exhaust leakage ahead of the upstream sensor, measured airflow and fuel delivery. On a V6, compare banks; on an inline-four, Bank 1 is the only bank.",symptoms:[{key:"idle",label:"Trim highest at idle",response:"Smoke-test the intake, PCV and brake-booster paths for unmetered air."},{key:"load",label:"Correction worsens with load",response:"Test fuel pressure/volume and airflow plausibility before replacing sensors."},{key:"refuel",label:"Rough after refueling",response:"Test the purge valve for physical leakage when commanded closed."},{key:"bank",label:"V6 Bank 1 only",response:"Inspect that bank's gasket, injectors and exhaust path; compare Bank 2."},{key:"cold",label:"Cold-start-only lean fault",response:"Compare ECT/IAT with ambient and inspect temperature-sensitive sealing."}],causes:[{cause:"Intake, PCV or booster vacuum leak",evidence:"Positive trim strongest at idle; smoke escapes",firstTest:"Regulated smoke test of the sealed intake"},{cause:"Purge valve leaking into the intake",evidence:"Post-refuel roughness or flow with command off",firstTest:"Command closed and verify physical sealing"},{cause:"Low fuel pressure or injector delivery",evidence:"Trim worsens with demand or one cylinder is lean",firstTest:"Use engine-specific pressure and contribution tests"},{cause:"Exhaust leak before the upstream sensor",evidence:"Cold tick/soot and false-lean response",firstTest:"Inspect and leak-test the upstream exhaust"},{cause:"Biased MAF/A/F sensor or circuit",evidence:"Physical/fuel checks pass and controlled response fails",firstTest:"Plausibility and circuit tests, not visual guessing"}],freezeFrame:[...commonFreeze,"STFT/LTFT Bank 1 and Bank 2 when available","MAF, MAP, A/F sensor and fuel-pressure data"],steps:[{title:"Save the trim pattern",detail:"Record idle and load correction before clearing."},{title:"Identify engine and bank layout",detail:"Separate inline-four, V6 and hybrid applications."},{title:"Compare operating states",detail:"Use idle-versus-airflow behavior to prioritize air or fuel."},{title:"Smoke-test and test purge",detail:"Prove unintended air/vapor flow."},{title:"Test fuel, exhaust and sensors",detail:"Follow evidence after leak checks."},{title:"Verify correction",detail:"Repeat the setting state and inspect pending codes."}],dontReplace:"Do not replace the upstream A/F sensor because it reports lean. A correct sensor often reports an intake leak, purge leak, low fuel delivery or exhaust leak accurately.",yearNotes:["Older cable/electronic-throttle engines, 2AR-FE and Dynamic Force A25A engines have different airflow and fuel-pressure specifications.","On a V6, P0171 is Bank 1; compare P0174 and Bank 2 data before calling a system-wide fuel fault."],faqs:[{question:"What does P0171 mean on a Camry?",answer:"The ECM reached excessive positive fuel correction on Bank 1."},{question:"Is the oxygen sensor bad?",answer:"Not automatically; it may be reporting a genuinely lean mixture."},{question:"Can a vacuum leak cause P0171?",answer:"Yes, especially when correction is greatest at idle."},{question:"Can a dirty MAF cause it?",answer:"A biased MAF can contribute, but test its response and the intake first."},{question:"Can I drive with P0171?",answer:"Limit load and diagnose promptly; stop for flashing misfire or severe symptoms."},{question:"Does Bank 1 identify a side on four-cylinders?",answer:"An inline-four has only one cylinder bank, so it is Bank 1."},{question:"Can purge create a lean code?",answer:"Yes, uncontrolled vapor/air flow can upset idle fuel control."},{question:"What proves the repair?",answer:"Normal trims in the original condition with no pending return."}]}),
page({slug:"p0441",code:"P0441",title:"P0441 Code Toyota Camry: Incorrect EVAP Purge Flow Diagnosis",description:"Diagnose Camry P0441 using fuel-cap evidence, purge and vent commands, tank-pressure response, EVAP smoke testing and generation-correct routing.",definition:"Evaporative Emission Control System Incorrect Purge Flow",severity:"Service soon",driveAdvice:"P0441 alone usually does not require stopping, but inspect promptly for liquid fuel leakage, a strong vapor odor, stalling or severe hard-start after refueling. Work outdoors or with approved ventilation and keep flame, sparks and unapproved pressure away from the EVAP system.",quickAnswer:"P0441 means the ECM did not observe the expected EVAP pressure change during a commanded purge test; it does not automatically mean the purge valve is bad. A loose cap, leak, restricted line, vent/closed-valve fault, purge valve or circuit, canister saturation, tank-pressure sensor bias and incorrect hose routing can all alter the result. Toyota's older 2AZ-FE documentation shows that the judgment depends on a sequence of valve states and pressure response.",symptoms:[{key:"refuel",label:"Hard start after refueling",response:"Test whether purge physically leaks while commanded off."},{key:"cap",label:"Code appeared after filling",response:"Inspect cap engagement, seal and filler surface before disturbing it further."},{key:"odor",label:"Fuel-vapor odor",response:"Inspect for liquid/vapor leakage promptly and avoid ignition sources."},{key:"click",label:"Valve clicks but code returns",response:"An electrical click does not prove flow rate or physical sealing."},{key:"none",label:"No drivability symptom",response:"Preserve fuel level and use commanded valve/tank-pressure tests."}],causes:[{cause:"Purge VSV leaking, restricted or electrically faulty",evidence:"Command and physical flow do not agree",firstTest:"Bidirectional command plus independent seal/flow test"},{cause:"Loose/damaged cap or EVAP leak",evidence:"Seal damage or regulated smoke escape",firstTest:"Inspect cap/filler then low-pressure smoke-test"},{cause:"Vent/closed-valve or switching-valve fault",evidence:"Tank pressure does not follow commanded sequence",firstTest:"Test each valve command, circuit and airflow"},{cause:"Saturated/damaged canister or restricted plumbing",evidence:"Liquid fuel, topping-off history or abnormal flow",firstTest:"Inspect canister and routing without applying shop air"},{cause:"Tank-pressure sensor bias or hose misrouting",evidence:"Implausible response or recent repair",firstTest:"Controlled pressure response and routing comparison"}],freezeFrame:[...commonFreeze,"Fuel level and time since refueling","Purge/vent commands and tank-pressure value"],steps:[{title:"Preserve EVAP context",detail:"Record fuel level, temperature, soak and companion codes."},{title:"Inspect cap and visible routing",detail:"Look for sealing damage or disconnected hoses."},{title:"Test purge off and on",detail:"Verify electrical action and physical sealing/flow."},{title:"Command other EVAP valves",detail:"Compare tank-pressure response with the expected sequence."},{title:"Smoke-test at regulated pressure",detail:"Inspect all connectors, canister and tank/filler seams."},{title:"Run the monitor correctly",detail:"Meet enable conditions and check pending status."}],dontReplace:"Do not replace the purge valve just because P0441 says purge flow. Toyota's monitor evaluates system pressure during a valve sequence, so leaks, vent control, restrictions, sensor bias and routing can imitate a purge-valve failure.",yearNotes:["Toyota's published 2002 2AZ-FE material describes an older Camry EVAP valve sequence; later leak-detection-pump systems require different service information.","Capless/conventional filler details and canister/valve locations vary by year; use VIN-correct routing."],deepDive:[{heading:"P0441 is a failed system response, not a named part",paragraphs:["On the older Toyota sequence, the ECM commands multiple valves and judges whether tank pressure falls as expected. A valve that cannot seal, a restriction, an opening elsewhere or a biased pressure signal can all produce the wrong response.","Record the original fuel-cap state before tightening or clearing. Then test electrical command separately from actual vapor flow so a clicking valve is not mistakenly declared good."]}],faqs:[{question:"Is P0441 usually a purge valve?",answer:"It is one possibility, but the complete EVAP response must be tested."},{question:"Can the gas cap cause P0441?",answer:"Yes on some monitor strategies, but inspect and test rather than guessing."},{question:"Can I drive?",answer:"Usually briefly if P0441 is alone; stop for liquid fuel or severe symptoms."},{question:"Why after refueling?",answer:"Cap sealing, excess vapor, canister saturation or leaking purge may become apparent."},{question:"Does a clicking valve pass?",answer:"No. It must also seal and flow correctly."},{question:"How is the leak found?",answer:"With regulated smoke, valve commands and tank-pressure response."},{question:"Can topping off matter?",answer:"Yes, liquid fuel can saturate the canister."},{question:"What proves repair?",answer:"Correct pressure response and a completed EVAP monitor without pending P0441."}],sources:[evapLogic]}),
page({slug:"p0455",code:"P0455",title:"P0455 Code Toyota Camry: Large EVAP Leak Testing",description:"Find Camry P0455 with fuel-cap and filler inspection, regulated smoke, purge/vent sealing, tank-pressure data and generation-specific EVAP routing.",definition:"Evaporative Emission System Leak Detected (Gross Leak/No Flow)",severity:"Service soon",driveAdvice:"P0455 alone is generally drivable for a short period, but stop and inspect for a liquid fuel leak, strong vapor odor, stalling or severe post-refuel trouble. Avoid flame and sparks, and never pressurize an EVAP system with unregulated shop air.",quickAnswer:"P0455 means the Camry's EVAP monitor could not establish or retain the expected vacuum/pressure and interpreted the failure as a gross leak or lack of flow. A missing/loose cap, disconnected hose, purge or vent valve held open, damaged canister, filler/tank seal, sensor bias or blockage can cause it. The code does not reveal the leak location or authorize a parts list.",symptoms:[{key:"cap",label:"Immediately after refueling",response:"Record and inspect cap engagement, seal and filler surface."},{key:"odor",label:"Strong fuel-vapor odor",response:"Inspect promptly for liquid/vapor leakage and avoid ignition sources."},{key:"stall",label:"Hard start or stall after filling",response:"Test purge for leakage into the intake."},{key:"other",label:"P0441 or vent code also set",response:"Diagnose commanded valve sequence and tank-pressure response together."},{key:"none",label:"Lamp only",response:"Use regulated smoke rather than visual guessing."}],causes:[{cause:"Missing, loose, wrong or damaged fuel cap/filler seal",evidence:"Cap/seal not seated or visibly damaged",firstTest:"Document original state and inspect correct cap/filler"},{cause:"Disconnected or split EVAP hose",evidence:"Visible opening or smoke escape",firstTest:"Regulated low-pressure smoke test"},{cause:"Purge or vent valve cannot seal",evidence:"Flow despite closed command",firstTest:"Command and physical sealing tests"},{cause:"Canister, pump-module or tank/filler seal leak",evidence:"Smoke at component seam",firstTest:"Test exact tank layout at regulated pressure"},{cause:"Pressure sensor bias or EVAP restriction",evidence:"Implausible response or no expected flow",firstTest:"Controlled sensor and flow test"}],freezeFrame:[...commonFreeze,"Fuel level, ambient temperature and soak","Tank pressure and purge/vent commands"],steps:[{title:"Save the monitor conditions",detail:"Keep fuel level, temperature and companion codes."},{title:"Inspect cap and filler",detail:"Document sealing before clearing."},{title:"Inspect visible hoses",detail:"Check engine bay and accessible underbody routing."},{title:"Command purge and vent",detail:"Separate electrical operation from physical sealing."},{title:"Smoke-test safely",detail:"Use EVAP-regulated pressure and inspect every seam."},{title:"Complete the monitor",detail:"Meet enable conditions and check pending codes."}],dontReplace:"Do not assume P0455 is always a cap. A disconnected hose or valve held open can look identical to the monitor, and a canister should be replaced only when testing shows leakage or contamination.",yearNotes:["Older Camry vacuum-switching-valve systems and newer leak-detection-pump systems do not share identical tests or component locations.","Hybrid and conventional gasoline Camry fuel-tank/EVAP layouts can differ; use the VIN-correct diagram."],deepDive:[{heading:"Gross leak describes monitor magnitude, not physical size",paragraphs:["A large pressure loss can come from a physical opening, but a valve commanded closed that remains open can create the same monitor result. Control each path and watch the tank-pressure response before replacing anything.","Inspect the cap first because it is quick, but proceed to regulated smoke if the sealing surface passes. Do not use pressure beyond Toyota's procedure; EVAP components are not designed for unrestricted shop air."]}],faqs:[{question:"Is P0455 always a loose gas cap?",answer:"No. Hoses, valves, canister and tank/filler seals can cause it."},{question:"Can I drive?",answer:"Usually briefly if alone, but not with liquid fuel or strong odor."},{question:"Can purge cause P0455?",answer:"Yes, if it cannot seal during the monitor."},{question:"How is the leak located?",answer:"With valve commands, tank-pressure data and regulated smoke."},{question:"Why did it return after a new cap?",answer:"The cap may not have been the leak or another EVAP fault remains."},{question:"Can topping off cause problems?",answer:"Yes, liquid fuel can damage or saturate the canister."},{question:"Why has readiness not completed?",answer:"Fuel level, soak and temperature may be outside enable conditions."},{question:"What proves repair?",answer:"The system seals and completes its EVAP monitor without a pending code."}]}),
page({slug:"p0300",code:"P0300",title:"P0300 Code Toyota Camry: Misfire Causes and Cylinder Tests",description:"Diagnose Camry P0300 by cylinder counters, plugs and coils, injector and fuel tests, compression, timing and 2018 V6 bulletin applicability.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing check-engine light means active catalyst-damaging misfire: release the throttle and stop safely. Do not continue highway driving or repeated load tests. A steady lamp with a smooth engine may permit a short trip for diagnosis, but stop for severe shaking, raw-fuel odor, overheating or mechanical noise.",quickAnswer:"P0300 means the ECM detected crankshaft-speed changes consistent with multiple/random misfire or without one cylinder dominating. It does not mean all coils are bad. Save P0301–P0306 codes, counters and freeze frame; identify one-cylinder, one-bank or whole-engine patterns; then test ignition, injector delivery, air/fuel supply, compression and timing. Toyota T-SB-0071-18 is a narrow branch for listed 2018 Camry 2GR-FKS V6 high-load/cylinder 5–6 cases.",symptoms:[{key:"flash",label:"Lamp flashes under load",response:"Stop load immediately; do not reproduce a converter-damaging event repeatedly."},{key:"cold",label:"Misfire only at cold start",response:"Capture early counters and inspect plug deposits, injector leakage and sealing."},{key:"one",label:"One cylinder leads",response:"Use one controlled coil/plug test, then injector and compression evidence."},{key:"bank",label:"One V6 bank dominates",response:"Inspect that bank's intake, fuel, harness, exhaust and valve timing."},{key:"2018",label:"2018 V6 under high load",response:"Check full T-SB-0071-18 VIN/calibration applicability before its repair path."}],causes:[{cause:"Worn/fouled plug, coil or connector fault",evidence:"Counter follows a controlled swap",firstTest:"Inspect plugs in cylinder order and move one known-good coil"},{cause:"Injector delivery or fuel-pressure problem",evidence:"Ignition passes; contribution/pressure differs",firstTest:"Engine-specific injector and pressure tests"},{cause:"Intake, PCV or purge air/vapor fault",evidence:"Fuel-trim/smoke evidence or post-refuel symptom",firstTest:"Smoke-test intake and test purge sealing"},{cause:"Compression, valve or head-gasket fault",evidence:"Misfire remains on cylinder and mechanical test fails",firstTest:"Relative compression then compression/leak-down"},{cause:"VVT/mechanical timing or calibration issue",evidence:"Correlation codes, phase data, repair history or matched TSB",firstTest:"Verify cam data/timing and bulletin applicability"}],freezeFrame:[...commonFreeze,"Cylinder-specific codes and misfire counters","Fuel trims, pressure and cam/VVT companion codes"],steps:[{title:"Preserve the pattern",detail:"Save codes, counters and freeze frame before clearing."},{title:"Classify cylinder, bank or system",detail:"Compare idle, cold and safe-load counts."},{title:"Inspect plugs and coils methodically",detail:"Change one variable at a time."},{title:"Test air, purge and fuel",detail:"Use trims, smoke and pressure evidence."},{title:"Measure mechanical condition",detail:"Use compression/leak-down when the fault stays."},{title:"Verify safely",detail:"Confirm stable counters without repeated flashing-lamp operation."}],dontReplace:"Do not install four or six coils, all injectors or an engine from P0300 alone. Toyota's 2018 V6 bulletin covers a defined model/engine and diagnostic pattern; it does not make every Camry misfire a calibration issue.",yearNotes:["T-SB-0071-18 Rev2 applies to listed 2018 Camry 2GR-FKS vehicles with defined high-load/misfire codes and possible cylinders 5/6.","Four-cylinder, V6 and hybrid engines use different cylinder layouts, ignition access, injectors and mechanical tests."],deepDive:[{heading:"The misfire counter pattern prevents shotgun repairs",paragraphs:["A cylinder that follows a controlled coil swap supports ignition. A cylinder that stays put after ignition passes needs injector contribution and mechanical sealing tests. Several cylinders with similar counts redirect attention toward air, fuel pressure, timing or voltage.","Only apply the 2018 V6 bulletin after matching the engine, VIN/calibration and operating pattern. A generic P0300 on another Camry still follows the normal Toyota diagnostic tree."]}],faqs:[{question:"Can I drive with P0300?",answer:"Stop for a flashing lamp or severe shaking; otherwise limit driving until diagnosed."},{question:"Does P0300 mean bad coils?",answer:"No. Fuel, air, compression, timing and wiring can cause it."},{question:"How do I find the cylinder?",answer:"Use P0301-series codes, counters and Mode $06 under the setting condition."},{question:"Can a bad injector cause it?",answer:"Yes, but test contribution and pressure before replacement."},{question:"Can low compression cause P0300?",answer:"Yes, particularly when one counter remains dominant."},{question:"Does the 2018 V6 bulletin apply to every Camry?",answer:"No, it has a narrow year, engine and condition range."},{question:"Should I clear the code first?",answer:"No; save freeze frame and counters first."},{question:"What proves repair?",answer:"Stable counters and no pending misfire under the original safe condition."}],sources:[misfireV6]}),
page({slug:"p0016",code:"P0016",title:"P0016 Code Toyota Camry: Cam-Crank Correlation Diagnosis",description:"Diagnose Camry P0016 using oil and VVT checks, desired-versus-actual cam angle, circuit waveforms and engine-specific mechanical timing verification.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1, Sensor A)",severity:"Stop soon",driveAdvice:"Minimize driving until oil pressure, abnormal chain/phaser noise and timing integrity are checked. Stop for hard starting, stalling, low-oil-pressure warning or persistent rattle. Do not repeatedly start or rev an engine that may be mechanically out of time.",quickAnswer:"P0016 means the Bank 1 intake-cam signal is outside its expected relationship to crankshaft position. ‘Sensor A’ identifies the intake cam, not a failed sensor. Incorrect oil level/viscosity, VVT oil control, actuator/phaser trouble, wiring or reluctor faults, mechanical timing and recent repair errors can all cause it. Camry engine generations use different timing drives and alignment procedures, so VIN/engine identification is mandatory.",symptoms:[{key:"noise",label:"Startup rattle",response:"Stop repeated starts and verify oil pressure and mechanical timing."},{key:"after",label:"Appeared after engine work",response:"Recheck timing, connectors, grounds, reluctors and required learning."},{key:"oil",label:"Oil low or wrong",response:"Correct specification/level and test pressure without assuming that is the only cause."},{key:"multi",label:"Several VVT/correlation codes",response:"Look for common oil, timing, power/ground or crank-signal faults."},{key:"drive",label:"Poor power or stalling",response:"Limit operation and confirm timing integrity before load testing."}],causes:[{cause:"Incorrect mechanical timing or worn timing components",evidence:"Noise, stable phase offset or recent internal work",firstTest:"Verify timing with the exact engine procedure/tools"},{cause:"Low, aerated, dirty or incorrect oil",evidence:"Level/specification/pressure abnormal",firstTest:"Verify oil and mechanical pressure where indicated"},{cause:"VVT oil-control valve or actuator fault",evidence:"Desired and actual cam angle do not track",firstTest:"Command VVT and test circuit/oil path"},{cause:"Cam/crank sensor, wiring or reluctor issue",evidence:"Dropout, circuit code or abnormal synchronized waveform",firstTest:"Load-test circuits and scope both signals"},{cause:"Calibration, relearn or repair-installation error",evidence:"Fault follows ECM/engine work",firstTest:"Confirm calibration, learned values and installation"}],freezeFrame:[...commonFreeze,"Desired/actual Bank 1 intake cam angle","Oil condition/pressure and all VVT/circuit companion codes"],steps:[{title:"Stop and inspect oil/noise",detail:"Do not repeatedly run a noisy engine."},{title:"Identify engine and sensor",detail:"Map Bank 1 Sensor A correctly."},{title:"Test VVT command and oil path",detail:"Graph desired versus actual angle."},{title:"Test cam/crank signals",detail:"Inspect circuits and synchronized waveforms."},{title:"Verify mechanical timing",detail:"Use engine-specific fixtures and marks."},{title:"Perform required learning",detail:"Confirm correlation and no pending return."}],dontReplace:"Do not replace the intake cam sensor because the code names camshaft position. A new sensor cannot correct low oil pressure, a sticking VVT actuator, damaged reluctor or mechanical timing installed one tooth out.",yearNotes:["2AZ-FE, 2AR-FE, 2GR-family and A25A engines do not share timing marks, actuator tests, torque procedures or learned-value requirements.","No broad Camry P0016 parts bulletin is represented here; use current VIN-correct Toyota repair information."],deepDive:[{heading:"A relationship code needs two signals and one mechanical truth",paragraphs:["Graph commanded and actual intake-cam angle, then inspect the synchronized cam/crank waveforms if the relationship remains abnormal. A clean sensor signal can still describe a camshaft that is physically out of time.","Recent chain, cylinder-head, engine or ECM work moves installation, grounds, connector placement and learned values near the top of the list. Without that history, follow oil/VVT and circuit evidence before opening the engine."]}],faqs:[{question:"Is P0016 a bad cam sensor?",answer:"Not necessarily; it is a cam-to-crank relationship code."},{question:"Which cam is Sensor A?",answer:"It normally identifies the Bank 1 intake cam, but confirm the engine manual."},{question:"Can wrong oil cause P0016?",answer:"It can disrupt hydraulic VVT control, but cannot explain every correlation fault."},{question:"Can I drive?",answer:"Avoid driving until noise, oil pressure and timing integrity are checked."},{question:"Can a timing chain cause it?",answer:"Yes, as can phaser, reluctor and installation faults."},{question:"Why after engine repair?",answer:"Timing, connectors, grounds or required learning may be incorrect."},{question:"Should both sensors be replaced?",answer:"No; test circuits and waveforms first."},{question:"What proves repair?",answer:"Desired/actual angle and cam-crank correlation remain correct without pending codes."}]}),
page({slug:"p0128",code:"P0128",title:"P0128 Code Toyota Camry: Thermostat, Coolant Sensor and Warm-Up Tests",description:"Diagnose Camry P0128 with cold-soak ECT/IAT comparison, coolant and thermostat checks, warm-up graphs and narrow 2010–2011 calibration guidance.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"Usually safe for a short diagnostic trip if coolant level is correct and there is no overheating, steam or heater loss. Stop for a red temperature warning, rapidly changing gauge, coolant leakage or an empty reservoir. Never remove a hot pressure cap.",quickAnswer:"P0128 means coolant temperature did not rise as quickly or as high as the ECM expected; it does not automatically prove the thermostat is stuck open. Verify cold coolant level, compare ECT and intake/ambient temperature after an overnight soak, graph warm-up while checking heater/radiator behavior, and test the sensor circuit. Toyota T-SB-0045-13 provides a calibration path only for specified 2010–2011 2AR-FE automatic Camrys when P0128 is the sole DTC.",symptoms:[{key:"slow",label:"Gauge warms slowly",response:"Graph ECT from a true cold start and observe radiator-hose warming."},{key:"heater",label:"Weak heat",response:"Check cold coolant level, air pockets and thermostat behavior."},{key:"normal",label:"Gauge looks normal",response:"The dash gauge is damped; compare scan ECT with monitor criteria."},{key:"after",label:"After cooling-system service",response:"Check fill/bleed, connector disturbance and thermostat orientation."},{key:"other",label:"Other temperature codes present",response:"The narrow Toyota calibration bulletin does not apply; diagnose those faults."}],causes:[{cause:"Thermostat leaking/stuck open or wrong temperature rating",evidence:"Slow warm-up and early radiator flow",firstTest:"Cold-start ECT graph plus hose/thermal observation"},{cause:"Low coolant or trapped air",evidence:"Level low, heater changes or recent service",firstTest:"Cold level, leak and proper bleed inspection"},{cause:"ECT sensor or circuit bias",evidence:"Cold ECT disagrees with IAT/ambient",firstTest:"Cold-soak plausibility and circuit test"},{cause:"Cooling fan commanded/running unnecessarily",evidence:"Fan operates cold without valid demand",firstTest:"Check commands, relays and companion codes"},{cause:"Calibration on covered 2010–2011 2AR-FE",evidence:"Exact application, P0128 alone and older calibration",firstTest:"Apply T-SB-0045-13 eligibility sequence"}],freezeFrame:[...commonFreeze,"Cold-soak ECT versus IAT/ambient","ECT warm-up curve, speed and heater/fan operation"],steps:[{title:"Check coolant cold",detail:"Inspect level and leaks without opening a hot system."},{title:"Compare cold sensors",detail:"ECT and IAT should be plausible near ambient after soak."},{title:"Graph the full warm-up",detail:"Watch temperature rise, fan and radiator-hose behavior."},{title:"Test thermostat and circuit",detail:"Separate physical cooling from biased data."},{title:"Check bulletin applicability",detail:"Match 2010–2011 2AR-FE, 6AT, VDS and sole-DTC rules."},{title:"Verify another cold start",detail:"Confirm normal warm-up and no pending code."}],dontReplace:"Do not replace the thermostat solely from P0128, and do not flash every 2010–2011 Camry. Toyota's bulletin requires an exact application and says it does not apply when other DTCs are present.",yearNotes:["T-SB-0045-13 applies to specified 2010–2011 Camry 2AR-FE with six-speed automatic, listed VDS/emissions configurations and P0128 alone.","Hybrid cooling systems include separate engine and inverter circuits; do not confuse their reservoirs or procedures."],deepDive:[{heading:"A true cold-soak graph is more useful than the dash gauge",paragraphs:["After an overnight soak, ECT and IAT should be plausible relative to ambient before startup. A biased ECT can make a healthy thermostat look slow, while a leaking thermostat produces a characteristic gradual warm-up and early radiator heat.","If the narrow bulletin matches, verify calibration and follow its sequence. If another DTC is present or the vehicle falls outside the table, Toyota directs normal repair-manual diagnosis."]}],faqs:[{question:"Does P0128 always mean a thermostat?",answer:"No. Coolant level, sensor bias, fan operation and calibration can contribute."},{question:"Can I drive?",answer:"Usually briefly if level and temperature are stable; stop for overheating or leakage."},{question:"Why is cabin heat weak?",answer:"A stuck-open thermostat, low coolant or air can reduce heat."},{question:"Can the temperature gauge look normal?",answer:"Yes; the ECM uses more precise scan data than the damped gauge."},{question:"Is there a Toyota bulletin?",answer:"Yes, for a narrow 2010–2011 2AR-FE automatic application."},{question:"Does that bulletin apply with other codes?",answer:"No; it explicitly redirects other-code cases to normal diagnosis."},{question:"How is the thermostat tested?",answer:"Use a cold-start temperature graph and cooling-system observations/specifications."},{question:"What proves repair?",answer:"A normal cold warm-up and completed monitor without pending P0128."}],sources:[coolant]}),
page({slug:"p1604",code:"P1604",title:"P1604 Code Toyota Camry: Startability Malfunction Diagnosis",description:"Diagnose Toyota Camry P1604 by preserving failed-start data and testing battery/cranking speed, fuel, ignition, immobilizer, airflow and mechanical condition.",definition:"Startability Malfunction",severity:"Diagnose promptly",driveAdvice:"P1604 records a starting-performance problem. If the engine now runs normally, drive only as needed for diagnosis. Stop repeated cranking if the battery slows, cables heat, fuel odor becomes strong or mechanical noise appears. Tow the car when it will not start, stalls in traffic or shows oil-pressure/overheating warnings.",quickAnswer:"Toyota P1604 means the ECM judged that the engine did not start or start normally under its monitoring conditions; it does not identify one failed part. Preserve all companion codes and the circumstances of the failed attempt. Test 12-volt battery state and cranking voltage/speed, fuel quantity and quality, fuel pressure/injector command, ignition, airflow/throttle, immobilizer authorization, engine speed/cam signals and compression. Hybrid READY behavior and engine cranking require hybrid-specific interpretation.",symptoms:[{key:"crank",label:"Cranks but will not start",response:"Verify rpm signal, fuel pressure/injection, spark and immobilizer status without extended cranking."},{key:"slow",label:"Cranks slowly",response:"Load-test the 12-volt battery and voltage-drop the starter cables/grounds."},{key:"brief",label:"Starts then stalls",response:"Check immobilizer, throttle/airflow, purge flooding and fuel delivery."},{key:"after",label:"After refueling or empty tank",response:"Verify fuel quantity/quality and purge leakage; do not rely only on the gauge."},{key:"hybrid",label:"Hybrid shows READY but engine behavior is unusual",response:"Use hybrid-aware data; READY time is not the same as engine run time."}],causes:[{cause:"Weak 12-volt battery, starter or cable voltage drop",evidence:"Low cranking speed/voltage or hot connection",firstTest:"Battery conductance/load and cranking voltage-drop tests"},{cause:"Fuel quantity, quality, pressure or injector fault",evidence:"No/incorrect pressure, contaminated fuel or absent contribution",firstTest:"Verify actual fuel and engine-specific delivery"},{cause:"Ignition, crank/cam signal or immobilizer problem",evidence:"No spark/rpm/synchronization or security status abnormal",firstTest:"Check companion codes, rpm/sync and authorization"},{cause:"Airflow, throttle or purge-flooding fault",evidence:"Post-refuel stall, abnormal throttle/MAF/MAP or excess vapor",firstTest:"Inspect air path and test purge sealing"},{cause:"Compression or mechanical timing problem",evidence:"Uneven/low cranking speed or correlation/noise",firstTest:"Relative compression then mechanical tests"}],freezeFrame:[...commonFreeze,"Cranking rpm and minimum voltage","Immobilizer/start authorization, fuel pressure and cam/crank sync"],steps:[{title:"Reconstruct the failed start",detail:"Record temperature, fuel level, crank duration and recent work."},{title:"Save all codes and data",detail:"Companion codes often identify the missing prerequisite."},{title:"Verify cranking quality",detail:"Test battery, speed and voltage drop."},{title:"Check authorization, spark and fuel",detail:"Follow the exact engine/hybrid sequence."},{title:"Test airflow and mechanical condition",detail:"Use purge, compression and timing evidence when basics pass."},{title:"Verify hot and cold restarts",detail:"Confirm normal start time without pending return."}],dontReplace:"Do not replace the starter, fuel pump or ECM from P1604 alone. It is an outcome code recording poor startability. Toyota flex-fuel P1604 bulletins for Tundra/Sequoia do not apply to a Camry.",yearNotes:["P1604 is Toyota-enhanced and scan tools may show subcodes or useful start-history data; use Toyota-capable diagnostics.","Do not apply T-SB-0166-19 or its obsolete predecessor to Camry; those bulletins list flex-fuel Tundra/Sequoia, not this model.","Hybrid Camry starting is managed by the hybrid system and requires model-specific READY, engine-speed and high-voltage safety procedures."],deepDive:[{heading:"P1604 describes the outcome of a start attempt",paragraphs:["The efficient path is to identify which prerequisite disappeared: adequate cranking speed, synchronized position signals, authorized start, correct air, fuel delivery, ignition and mechanical compression. Companion codes and cranking PIDs are more useful than the P1604 label alone.","Ask whether the tank ran empty, the battery was disconnected, keys or remote-start equipment changed, fuel was added, or engine work preceded the event. Those details determine which test comes first."]}],faqs:[{question:"What does Toyota P1604 mean?",answer:"The ECM detected abnormal or failed engine starting performance."},{question:"Does it mean a bad starter?",answer:"No. Battery, fuel, ignition, authorization, airflow and mechanical faults are possible."},{question:"Can a weak battery set it?",answer:"Yes, if cranking voltage or speed becomes inadequate."},{question:"Can running out of fuel set it?",answer:"A failed start from insufficient fuel can contribute; verify actual quantity."},{question:"Is it a Camry flex-fuel software issue?",answer:"No Toyota bulletin cited for that condition lists Camry."},{question:"Can I clear it?",answer:"Save codes and failed-start data first, then clear only after diagnosis."},{question:"Does hybrid Camry diagnosis differ?",answer:"Yes. READY status and engine cranking require hybrid-aware tools and safety."},{question:"What proves repair?",answer:"Reliable cold/hot restarts with normal cranking data and no pending return."}]}),
page({slug:"p0101",code:"P0101",title:"P0101 Code Toyota Camry: MAF Range and Airflow Diagnosis",description:"Diagnose Camry P0101 with air-filter and duct inspection, MAF/MAP/throttle plausibility, fuel trims, leak tests and engine-specific airflow data.",definition:"Mass or Volume Air Flow Circuit Range/Performance",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration if the Camry hesitates, runs rich/lean or has reduced power. Stop for stalling in traffic, a flashing misfire lamp, severe smoke or overheating. A steady lamp with stable operation may permit a short diagnostic trip.",quickAnswer:"P0101 means MAF-reported airflow did not agree with the ECM's expected range for engine speed, throttle, pressure and other conditions. It does not automatically mean the MAF sensor failed. Inspect the correct air filter, housing, duct and clamps; smoke-test for unmetered air; compare MAF, MAP, throttle and fuel trims; then test the sensor circuit. Intake restriction, leaks, contamination, purge flow, mechanical breathing and incorrect learned values can all create a rationality failure.",symptoms:[{key:"after",label:"After air-filter service",response:"Check filter fit, housing seal, duct clamps and sensor connector/orientation."},{key:"idle",label:"Rough idle with lean trim",response:"Smoke-test intake/PCV and test purge sealing."},{key:"load",label:"Poor power under load",response:"Check restriction and graph airflow against rpm/load."},{key:"rich",label:"Black smoke or rich correction",response:"Inspect biased airflow, fuel pressure/injectors and restricted intake."},{key:"inter",label:"Intermittent over bumps",response:"Inspect pin fit, harness tension and grounds while graphing."}],causes:[{cause:"Loose/split intake duct or unmetered-air leak",evidence:"Smoke escape or trim strongest at idle",firstTest:"Inspect and regulated smoke-test downstream of MAF"},{cause:"Wrong, restricted or poorly seated air filter/housing",evidence:"Recent service or abnormal restriction",firstTest:"Compare correct filter and inspect clean/dirty sides"},{cause:"Contaminated/biased MAF or circuit fault",evidence:"PID or electrical response fails controlled test",firstTest:"Circuit, power/ground and known-condition plausibility"},{cause:"MAP/throttle/purge input distorting airflow model",evidence:"Companion codes or command/response mismatch",firstTest:"Cross-check sensors and purge sealing"},{cause:"Mechanical breathing, VVT or exhaust restriction",evidence:"Airflow remains low with intake/sensors proven",firstTest:"VVT, compression and exhaust backpressure tests"}],freezeFrame:[...commonFreeze,"MAF, MAP, throttle angle and calculated load","STFT/LTFT and companion airflow/VVT codes"],steps:[{title:"Preserve the airflow snapshot",detail:"Record units and all related PIDs."},{title:"Identify engine/filter application",detail:"Confirm stock intake and correct parts."},{title:"Inspect and leak-test",detail:"Check the full metered-air path and PCV."},{title:"Cross-check MAF/MAP/throttle",detail:"Use cold KOEO and warm operating data."},{title:"Test circuits and engine breathing",detail:"Proceed only after physical checks."},{title:"Verify through safe airflow range",detail:"Confirm plausible data and no pending P0101."}],dontReplace:"Do not replace or repeatedly clean the MAF because P0101 contains its name. A performance code can be set by leaks, restriction, incorrect installation, other sensor inputs, purge flow or mechanical airflow.",yearNotes:["MAF scaling, units and expected grams-per-second vary by engine displacement, altitude and temperature; do not use one internet idle number as a pass/fail specification.","Aftermarket oiled filters or intake systems can contaminate or alter metering and should be disclosed."],deepDive:[{heading:"Plausibility uses several sensors at once",paragraphs:["Compare key-on MAP with local barometric pressure, then evaluate MAF, MAP, throttle and load together during a stable warm idle and safe higher airflow. A sensor can produce a believable voltage yet still be biased relative to the engine's actual breathing.","Physical inspection comes first. A housing left open after filter service or a split downstream duct makes correctly measured air disagree with oxygen-sensor fuel correction and can falsely implicate electronics."]}],faqs:[{question:"Does P0101 mean the MAF is bad?",answer:"No. It means measured airflow failed a plausibility check."},{question:"Can an intake leak cause it?",answer:"Yes, especially downstream of the MAF."},{question:"Can I clean the sensor?",answer:"Only with an approved method after inspection; cleaning is not a circuit test."},{question:"Can a dirty filter cause P0101?",answer:"A severe restriction or incorrect installation can contribute."},{question:"Can purge cause it?",answer:"Unexpected vapor/air flow can upset the airflow model."},{question:"Can I drive?",answer:"Limit load; stop for stalling, flashing misfire or severe symptoms."},{question:"What data should I graph?",answer:"MAF, MAP, throttle, load, rpm and both fuel trims."},{question:"What proves repair?",answer:"Plausible airflow across the original condition with no pending code."}]}),
page({slug:"p0138",code:"P0138",title:"P0138 Code Toyota Camry: Bank 1 Sensor 2 High Voltage Diagnosis",description:"Diagnose Camry P0138 with downstream oxygen-sensor graphs, wiring and exhaust tests, mixture checks and Toyota's narrow older-engine calibration guidance.",definition:"Oxygen Sensor Circuit High Voltage (Bank 1, Sensor 2)",severity:"Service soon",driveAdvice:"P0138 alone usually permits a short diagnostic trip, but stop for a flashing misfire lamp, raw-fuel odor, black smoke, overheating catalyst or severe poor running. A rich-running engine can damage the converter, so diagnose companion fuel and misfire codes promptly.",quickAnswer:"P0138 means the Bank 1 downstream oxygen-sensor circuit remained above its expected voltage range/response. It does not prove that sensor failed or that the catalyst is bad. Check companion rich/lean and A/F-sensor codes, exhaust integrity, connector/wiring shorts and controlled downstream response. Toyota published two narrow older-Camry paths: 2007–2010 V6 guidance involving upstream A/F-sensor response, and 2010–2011 non-PZEV 2AR-FE calibration guidance.",symptoms:[{key:"rich",label:"Black smoke or fuel odor",response:"Stop extended driving and diagnose actual rich operation/injector or pressure faults."},{key:"with",label:"P2195/P2197 also present",response:"Use Toyota's matched older-application guidance and test upstream A/F response."},{key:"after",label:"After exhaust or sensor work",response:"Verify Bank 1 Sensor 2 identity, connector placement and harness routing."},{key:"fixed",label:"Signal stays high key-on/engine-off",response:"Test for signal short/reference contamination before replacing the sensor."},{key:"alone",label:"No drivability symptom",response:"Graph downstream response and apply circuit tests under the setting condition."}],causes:[{cause:"Downstream oxygen sensor or circuit short",evidence:"Signal/circuit fails controlled electrical test",firstTest:"Inspect routing and load-test signal/ground circuits"},{cause:"Actual rich exhaust from fueling fault",evidence:"Fuel trims, smoke/deposits or companion rich codes",firstTest:"Diagnose fuel pressure, injectors and purge"},{cause:"Incorrect upstream A/F sensor response on covered older V6",evidence:"Matched VDS/year and companion P2195/P2197 pattern",firstTest:"Apply T-SB-0001-10 applicability and test sequence"},{cause:"Calibration condition on covered non-PZEV 2AR-FE",evidence:"Matched 2010–2011 application/calibration",firstTest:"Follow T-SB-0151-18 after normal checks"},{cause:"Connector mix-up, contamination or exhaust issue",evidence:"Recent work, damaged harness or abnormal leak/temperature",firstTest:"Verify sensor identity, connections and exhaust integrity"}],freezeFrame:[...commonFreeze,"Bank 1 Sensor 2 voltage/current as supported","Upstream A/F data, fuel trims and P2195/P2197/P0606 companions"],steps:[{title:"Map Bank 1 Sensor 2",detail:"Identify downstream sensor for the exact engine."},{title:"Save companion-code context",detail:"Rich/lean, A/F and circuit codes change priority."},{title:"Inspect wiring and exhaust",detail:"Check heat damage, crossed connectors and leaks."},{title:"Test actual mixture",detail:"Use trims, plugs, fuel pressure and purge evidence."},{title:"Apply narrow Toyota guidance",detail:"Match VDS, engine, emissions and calibration."},{title:"Verify controlled response",detail:"Confirm normal downstream behavior and no pending code."}],dontReplace:"Do not replace Bank 1 Sensor 2 or the converter from P0138 alone. Toyota documents older cases where upstream A/F-sensor response or calibration influenced the downstream code, and wiring or real rich operation must also be excluded.",yearNotes:["T-SB-0001-10 Rev1 lists specific 2007–2010 Camry V6 VDS applications and possible P0138/P0158 with P2195/P2197; match the table.","T-SB-0151-18 covers non-PZEV 2010–2011 Camry 2AR-FE only; identify emissions certification and calibration.","Later wideband/downstream sensor strategies require their own Toyota repair-manual data."],deepDive:[{heading:"Downstream high voltage may originate upstream",paragraphs:["First determine whether the exhaust is actually rich. If fuel control is normal, inspect the downstream circuit for a short and verify response during a controlled test. If companion A/F codes and an exact older application match, Toyota's bulletin may redirect diagnosis to upstream sensor response/calibration.","Bank 1 Sensor 2 is downstream of the catalyst, but location and connector routing change with the four-cylinder/V6 layout. Confirm identity before unplugging or ordering parts."]}],faqs:[{question:"What does P0138 mean?",answer:"The Bank 1 downstream oxygen-sensor circuit stayed higher than expected."},{question:"Is Sensor 2 downstream?",answer:"Yes, but confirm the exact engine's layout and connector."},{question:"Does it mean a bad converter?",answer:"No. The code is a sensor-circuit/response fault, not a catalyst verdict."},{question:"Can rich running cause it?",answer:"Yes; diagnose fuel and purge causes when other evidence supports rich exhaust."},{question:"Can wiring cause it?",answer:"Yes, heat damage or a signal short can hold voltage high."},{question:"Is there Toyota guidance?",answer:"Yes for narrow older V6 and non-PZEV 2AR-FE applications."},{question:"Can I drive?",answer:"Usually briefly if alone; stop for raw fuel, smoke or flashing misfire."},{question:"What proves repair?",answer:"Normal controlled response, corrected mixture/circuit and no pending P0138."}],sources:[oxygenOld,oxygen2ar]}),
];
